", argv[0]); exit(0); } if (inet_aton(argv[1], &addr) != 0) { host_p = gethostbyaddr((const char*)&addr, sizeof(addr), AF_INET); } else { host_p = gethostbyname(argv[1]); } printf("official hostname: %s
:", host_p->h_name); for (pp = host_p->h_aliases; *pp != NULL; pp++) { printf("alias: %s
", *pp); } for (pp = host_p->h_addr_list; *pp != NULL; pp++) { addr.s_addr = ((struct in_addr *)*pp)->s_addr; printf("address: %s
