function boldify(parts, ...insertedParts) { return parts .map((s, i) => { if (i === insertedParts.length) return s return `${s}<strong>${insertedParts[i]}</strong>` }) .join('') } const name = 'Sabertaz' console.log(boldify`Hi, my name is ${name}!`) // => "Hi, my name is <strong>Sabertaz</strong>!" function template(strings, ...keys) { return function (...values) { const dict = values[values.length - 1] || {} const result = [strings[0]] keys.forEach((key, i) => { const value = Number.isInteger(key) ? values[key] : dict[key] result.push(value, strings[i + 1]) }) return result.join('') } } const t1Closure = template`${0}${1}${0}!` t1Closure('Y', 'A') // "YAY!" const t2Closure = template`${0} ${'foo'}!` t2Closure('Hello', { foo: 'World' }) // "Hello World!" 编译模板 (小型模板引擎): function compile(template) { const evalExpr = /<%=(.+?)%>/g const expr = /<%([\s\S]+?)%>/g template = template .replace(evalExpr, '`); 
 echo( $1 ); 
